import unittest

def add(a, b):
    """Add two integers."""
    return a + b

class TestAdd(unittest.TestCase):
    def test_addPositive(self):
        self.assertEqual(add(2, 3), 5)
    def test_addNegative(self):
        self.assertEqual(add(-2, 2), 0)

if __name__ == "__main__":
    unittest.main()
